import re

ANSI = re.compile(r"\x1b\[[0-9;]*[A-Za-z]|\r")
SECTION = re.compile(r"^section_(?P<event>start|end):(?P<ts>\d+):(?P<section>\w+)(?:\r?\x1b\[0K(?P<title>.*?))?\s*$")
RUNNER = re.compile(r"^Running with gitlab-runner (?P<version>\S+) \((?P<revision>\w+)\)\s*$")
HOST = re.compile(r"^\s+on (?P<runner>\S+) (?P<token>\S+), system ID: (?P<system_id>\S+)\s*$")
RESULT = re.compile(r"^(?P<level>ERROR|WARNING): (?P<message>\S.*?)\s*$")
COMMAND = re.compile(r"^\$ (?P<command>\S.*?)\s*$")


def parse(lines):
    runner = {"name": "runner", "kind": "kv", "lines": [], "records": [{}]}
    sections = {"name": "sections", "kind": "table", "lines": [], "records": []}
    commands = {"name": "commands", "kind": "table", "lines": [], "records": []}
    log = {"name": "log", "kind": "table", "lines": [], "records": []}
    result = {"name": "result", "kind": "kv", "lines": [], "records": []}
    skip, open_sections, section, want_title = [], {}, "", None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        text = ANSI.sub("", ln).strip()
        if not text:
            skip.append(i)
            continue
        if want_title is not None and ln.startswith("\x1b[0K"):
            # the title printed after a \r on the section_start line
            want_title["Title"] = text
            sections["lines"].append(i)
            want_title = None
            continue
        want_title = None
        m = SECTION.match(ln)
        if m:
            name = m.group("section")
            if m.group("event") == "start":
                rec = {"Section": name, "Title": (m.group("title") or "").strip(),
                       "Start": m.group("ts"), "End": "", "Duration (s)": ""}
                sections["records"].append(rec)
                open_sections[name], section = rec, name
                if not rec["Title"]:
                    want_title = rec
            else:
                rec = open_sections.pop(name, None)
                if rec is not None:
                    rec["End"] = m.group("ts")
                    rec["Duration (s)"] = int(m.group("ts")) - int(rec["Start"])
                section = ""
            sections["lines"].append(i)
            continue
        m = RUNNER.match(ln)
        if m:
            runner["records"][0].update({"Version": m.group("version"), "Revision": m.group("revision")})
            runner["lines"].append(i)
            continue
        m = HOST.match(ln)
        if m:
            runner["records"][0].update({"Runner": m.group("runner"), "Token": m.group("token"),
                                         "System ID": m.group("system_id")})
            runner["lines"].append(i)
            continue
        m = RESULT.match(text)
        if m and not section:
            result["records"].append({m.group("level"): m.group("message")})
            result["lines"].append(i)
            continue
        m = COMMAND.match(text)
        if m:
            commands["records"].append({"Section": section, "Command": m.group("command")})
            commands["lines"].append(i)
            continue
        log["records"].append({"Section": section, "Message": text})
        log["lines"].append(i)
    return {"blocks": [runner, sections, commands, log, result], "skip": skip}
